    this.fstate.dc_quant = (VP56_DC_QUANTS[hdr.quant] * 4) | 0;
    this.fstate.ac_quant = (VP56_AC_QUANTS[hdr.quant] * 4) | 0;
    this.loop_thr = (VP56_FILTER_LIMITS[hdr.quant]) | 0;
   
