  function avm2_global_init_early_classes(activation, tunit) {
    var object_i_class = Avm2Class.customNew(new Avm2QName(Avm2Namespace.any(), "Object"));
    var class_i_class = Avm2Class.customNew(new Avm2QName(Avm2Namespace.any(), "Class"));
    activation.domain.export_class(object_i_class.name, object_i_class);
    activation.domain.export_class(class_i_class.name, class_i_class);
    activation.avm2.system_class_defs = new Avm2SystemClassDefs(object_i_class, class_i_class);
  } 

