  Avm2Domain.uninitializedDomain = function(parent) {
    var domain = new Avm2Domain();
    domain.parent = parent;
    return domain;
  }
  Avm2Domain.prototype.has_definition = function(name) {
    if (this.defs.contains_key(name)) {
      return true;
    }
    if (this.parent) {
      return this.parent.has_definition(name);
    }
    return false;
  }
  Avm2Domain.prototype.has_class = function(name) {
    if (this.classes.contains_key(name)) {
      return true;
    }
    if (this.parent) {
      return this.parent.has_class(name);
    }
    return false;
  }
  Avm2Domain.prototype.export_definition = function(name, script) {
    if (this.has_definition(name)) return;
    this.defs.insert_at_end(name, script);
  }
  Avm2Domain.prototype.export_class = function(export_name, _class) {
    if (this.has_class(export_name)) return;
    this.classes.insert_at_end(export_name, _class);
  }
