  Avm2Activation.prototype.op_type_of = function() {
    var value = this.popStack();
    var type_name;
    switch(value.a) {
      case Avm2Value.Undefined:
        type_name = "undefined";
        break;
      case Avm2Value.Null:
        type_name = "object";
        break;
      case Avm2Value.Bool:
        type_name = "boolean";
        break;
      case Avm2Value.Number:
      case Avm2Value.Integer:
        type_name = "number";
        break;
      case Avm2Value.Object:
        type_name = "object";
        break;
      case Avm2Value.String:
        type_name = "string";
        break;
    }
    this.pushStack(Avm2Value.fromString(type_name));
  }
