  function scaleMat(mat, sx, sy) {
    mat[0] *= sx;
    mat[1] *= sy;
    mat[2] *= sx;
    mat[3] *= sy;
    mat[4] *= sx;
    mat[5] *= sy;
  }
  function translateMat(mat, dx, dy) {
    mat[4] += dx;
    mat[5] += dy;
  }
  function invertMat(mat) {
    var det = mat[0] * mat[3] - mat[2] * mat[1];
    var tx = (mat[3] * mat[4] - mat[2] * mat[5]) / -det;
    var ty = (mat[1] * mat[4] - mat[0] * mat[5]) / det;
    var a = mat[3] / det;
    var b = mat[1] / -det;
    var c = mat[2] / -det;
    var d = mat[0] / det;
    mat[0] = a;
    mat[1] = b;
    mat[2] = c;
    mat[3] = d;
    mat[4] = tx;
    mat[5] = ty;
  }
